import {useState} from 'react';
import {api} from './api';
import {Blank,Feedback,Section} from './common';
import {Drawer,Field,Form} from './ui';
import {platform,timestamp,useResource} from './data';
export default function Community({feed=false}){if(feed)return <ReviewFeed/>;return <Communities/>;}
function ReviewFeed(){const r=useResource(()=>api('/community/feed'));return <><div className="page-heading"><div><h1>Community voices.</h1><p>Organization and product conversations, with reviews from completed orders.</p></div><button className="secondary" onClick={r.refresh}>Refresh feed</button></div><Feedback resource={r}/>{r.data?<Section title="Latest experiences"><ul className="event-list review-feed">{r.data.reviews.map(p=><li key={p.id}><div className="review-identity">{p.avatar?<img src={p.avatar} alt=""/>:<span className="organization-logo">{p.author_name.slice(0,1)}</span>}<div><strong>{p.author_name}</strong><p>{p.organization_name}{p.product_name?` · ${p.product_name}`:null} · {p.kind==='review'?`${p.rating} / 5 · Verified purchase`:'Public comment'}</p></div></div><p className="message-body">{p.body}</p><small>{timestamp(p.created_at)}</small></li>)}</ul>{!r.data.reviews.length?<Blank title="No reviews yet.">Reviews of organizations and their purchased products appear here after a delivered order.</Blank>:null}</Section>:null}</>;}
function Communities(){
 const r=useResource(()=>api('/community/communities')),[selected,setSelected]=useState(null),[creating,setCreating]=useState(false),[error,setError]=useState('');
 const membership=async c=>{try{setError('');await api(`/community/communities/${c.id}/${c.joined?'leave':'join'}`,'POST',{});setSelected(null);await r.refresh();}catch(e){setError(e.message);}};
 return <><div className="page-heading"><div><h1>Your community, connected.</h1><p>Public conversations, shared updates and local connection.</p></div><button className="primary" onClick={()=>setCreating(true)}>Create community</button></div><p className="small muted">Riders can belong to at most five communities. These are public discussions, not private organization messages.</p><Feedback resource={r}/>{error?<p role="alert" className="error">{error}</p>:null}{r.data?<Section title="Communities"><ul className="event-list">{r.data.communities.map(c=><li key={c.id}><div className="section-heading"><div><h3>{c.name}</h3><small>{c.country} · {c.member_count} members</small></div><div className="action-tabs"><button className="secondary" onClick={()=>membership(c)}>{c.joined?'Leave':'Join'}</button><button className="text-button" onClick={()=>setSelected(c)}>View posts</button></div></div></li>)}</ul>{!r.data.communities.length?<Blank title="No communities yet.">Start a community and invite people to join.</Blank>:null}</Section>:null}{selected?<Drawer title={selected.name} onClose={()=>setSelected(null)}><CommunityPosts community={selected}/></Drawer>:null}{creating?<Drawer title="Create a community" onClose={()=>setCreating(false)}><Form submit="Create community" onSubmit={async d=>{await api('/community/communities','POST',{...d,country:d.country.toUpperCase()});setCreating(false);await r.refresh();}}><Field label="Community name" name="name" required maxLength={100}/><Field label="Country code" name="country" required pattern="[A-Za-z]{2}" maxLength={2}/></Form></Drawer>:null}</>;
}
function CommunityPosts({community}){const r=useResource(()=>api(`/community/communities/${community.id}/posts`),[community.id]);return <><Feedback resource={r}/>{community.joined?<Form submit="Publish post" onSubmit={async d=>{await api(`/community/communities/${community.id}/posts`,'POST',d);await r.refresh();}}><Field label="Post"><textarea name="body" required maxLength={2000}/></Field></Form>:<p className="notice">Join this community to post or comment.</p>}{r.data?<ul className="event-list">{r.data.posts.map(p=><li key={p.id}><strong>{p.author_name}</strong><p className="message-body">{p.body}</p><small>{timestamp(p.created_at)}</small><Comments post={p} joined={community.joined}/></li>)}</ul>:null}</>;}
function Comments({post,joined}){const [show,setShow]=useState(false);return <><button className="text-button" onClick={()=>setShow(!show)}>{show?'Hide comments':`${post.comment_count} comments`}</button>{show?<CommentList post={post} joined={joined}/>:null}</>;}
function CommentList({post,joined}){const r=useResource(()=>api(`/community/posts/${post.id}/comments`),[post.id]);return <div className="service-panel"><Feedback resource={r}/>{r.data?<ul className="event-list">{r.data.comments.map(c=><li key={c.id}><p className="message-body">{c.body}</p><small>{timestamp(c.created_at)}</small></li>)}</ul>:null}{joined?<Form submit="Post comment" onSubmit={async d=>{await api(`/community/posts/${post.id}/comments`,'POST',d);await r.refresh();}}><Field label="Comment"><textarea name="body" required maxLength={1000}/></Field></Form>:null}</div>;}
export function StorefrontReviews({id,productId}){const r=useResource(async()=>{const [reviews,orders]=await Promise.all([api(`/community/organizations/${id}/reviews`),platform('/orders')]);return {...reviews,orders:orders.orders.filter(o=>o.organization_id===id&&o.state==='delivered')};},[id]),[notice,setNotice]=useState('');return <Section title="Public organization reviews"><StoreComments id={id} productId={productId}/><Feedback resource={r}/>{r.data?<><p>{r.data.summary.count?`${Number(r.data.summary.average).toFixed(1)} / 5 from ${r.data.summary.count} reviews`:'No reviews yet.'}</p><ul className="event-list">{r.data.reviews.map(review=><li key={review.id}><strong>{review.author_name} · {review.rating} / 5</strong><p className="message-body">{review.body}</p><small>{timestamp(review.created_at)}</small></li>)}</ul>{r.data.orders.length?<div className="form-panel"><h3>Review a completed order</h3><Form submit="Publish review" onSubmit={async d=>{await api(`/community/organizations/${id}/reviews`,'POST',{...d,rating:Number(d.rating)});setNotice('Your public review is published.');await r.refresh();}}><Field label="Delivered order"><select name="orderId">{r.data.orders.map(o=><option key={o.id} value={o.id}>{o.id.slice(0,8)}</option>)}</select></Field><Field label="Rating"><select name="rating">{[5,4,3,2,1].map(n=><option key={n} value={n}>{n} / 5</option>)}</select></Field><Field label="Your experience"><textarea name="body" maxLength={2000} required/></Field></Form></div>:<p className="small muted">Only customers with a delivered purchase can publish a review.</p>}{notice?<p role="status" className="notice">{notice}</p>:null}</>:null}</Section>;}

function StoreComments({id,productId}){const r=useResource(()=>api(`/community/organizations/${id}/comments`),[id]),[notice,setNotice]=useState('');return <div className="service-panel"><h3>Public conversation</h3><p className="small muted">Comments are visible to all customers in Community. Keep delivery addresses and private contact details out of your post.</p><Feedback resource={r}/><Form submit="Publish comment" onSubmit={async d=>{await api(`/community/organizations/${id}/comments`,'POST',{...d,...(productId?{productId}:{})});setNotice('Your comment is published in the public community feed.');await r.refresh();}}><Field label={productId?'Comment on this product':'Comment on this organization'}><textarea name="body" maxLength={2000} required/></Field></Form>{notice?<p role="status" className="notice">{notice}</p>:null}<ul className="event-list">{r.data?.comments.map(c=><li key={c.id}><strong>{c.author_name}</strong>{c.product_name?<p className="small">{c.product_name}</p>:null}<p className="message-body">{c.body}</p><small>{timestamp(c.created_at)}</small></li>)}</ul></div>;}
